// v2 — sin LLM. Arma el mensaje fijo de Edgardo con el nombre del lead.
// Si no hay nombre capturado, usa fallback genérico "Hola, buen día.".
const lead = $input.first().json;
const sessionId = String(lead.session_id || '');
const parts = sessionId.split('_');
const canal = parts[0] || 'unknown';
const subscriberId = parts.slice(1).join('_') || '';

const datos = lead.datos_capturados || {};
const nombreRaw = String(datos.nombre || '').trim();
// Solo usa primer nombre, capitalizado, para evitar "Hola, JUAN CARLOS DEL VALLE".
const primerNombre = nombreRaw.split(/\s+/)[0] || '';
const nombreFmt = primerNombre
  ? primerNombre.charAt(0).toUpperCase() + primerNombre.slice(1).toLowerCase()
  : '';

const saludo = nombreFmt
  ? `Hola, ${nombreFmt}, buen día.`
  : 'Hola, buen día.';

const mensaje = `${saludo} Quería dar seguimiento a nuestra última conversación y saber si te quedó alguna consulta pendiente. Si es así, avísame y nos ponemos en contacto de inmediato. ¡Saludos!`;

return [{
  json: {
    session_id: sessionId,
    subscriber_id: subscriberId,
    canal,
    nombre: nombreFmt,
    ai_msg_1: mensaje,
    ai_msg_2: '',
    ai_msg_3: '',
    ai_msg_count: 1
  }
}];

